const query = $json.query ?? {};

const allowedChains = new Map([
  ["netto", "Netto"],
  ["rema 1000", "REMA 1000"],
  ["rema1000", "REMA 1000"],
  ["365discount", "365discount"],
  ["365", "365discount"]
]);

const allowedCategories = new Set([
  "frugt og grønt",
  "kød og fjerkræ",
  "fisk og skaldyr",
  "mejeri og køl",
  "brød og bager",
  "kolonial",
  "frost",
  "drikkevarer",
  "slik og snacks",
  "husholdning og rengøring",
  "personlig pleje",
  "baby",
  "kæledyr",
  "blomster og planter",
  "andet"
]);

const allowedStatuses = new Set([
  "exceptional",
  "good",
  "current_cheapest",
  "normal",
  "currently_comparable",
  "expensive",
  "unverified"
]);

function cleanOptionalString(value, maxLength = 100) {
  if (
    value === null ||
    value === undefined
  ) {
    return null;
  }

  const cleaned = String(value).trim();

  if (!cleaned) {
    return null;
  }

  return cleaned.slice(0, maxLength);
}

function parseInteger(value, fallback, min, max) {
  const parsed = Number.parseInt(value, 10);

  if (!Number.isFinite(parsed)) {
    return fallback;
  }

  return Math.min(
    Math.max(parsed, min),
    max
  );
}

const rawChain =
  cleanOptionalString(query.chain, 50)
    ?.toLocaleLowerCase("da-DK") ?? null;

const chainName =
  rawChain
    ? allowedChains.get(rawChain) ?? null
    : null;

if (rawChain && !chainName) {
  throw new Error(
    `Ukendt kæde: ${query.chain}`
  );
}

const category =
  cleanOptionalString(query.category, 100)
    ?.toLocaleLowerCase("da-DK") ?? null;

if (
  category &&
  !allowedCategories.has(category)
) {
  throw new Error(
    `Ukendt kategori: ${query.category}`
  );
}

const status =
  cleanOptionalString(query.status, 50)
    ?.toLocaleLowerCase("da-DK") ?? null;

if (
  status &&
  !allowedStatuses.has(status)
) {
  throw new Error(
    `Ukendt status: ${query.status}`
  );
}

const search =
  cleanOptionalString(query.search, 100);

const limit =
  parseInteger(
    query.limit,
    50,
    1,
    100
  );

const offset =
  parseInteger(
    query.offset,
    0,
    0,
    100000
  );

return {
  json: {
    chainName,
    category,
    status,
    search,
    limit,
    offset
  }
};
